"@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@300;400;500;700&display=swap');

* {
    padding: 0;
    margin: 0;
    box-sizing: border-box;
    font-family: "Roboto", sans-serif;
}

#landing {
    min-height: 100vh;
}

html {
    scroll-behavior: smooth;
}

.row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    max-width: 2000px;
    margin: 0 auto;
    padding: 0 24px;
}

.container {
    padding: 20px 0;
}

.title {
  font-size: 50px;
  margin-bottom: 12px;
  text-align: center;
  line-height: 1;
}

.purple.script {
    color: #7a3cff;
    font-family: 'Permanent Marker', cursive;
    letter-spacing: 4px;
}

.purple.fade-in {
    font-weight: 700; 
}

.purple {
    color: #7a3cff;
}

a {
  text-decoration: none;
}

/* Navigation */
nav {
   width: 100%;
   padding: 5px 5px;
}

.nav__logo--img {
    height: 140px; 
    width: 160px;
}

.nav__row {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.nav__logo {
    display: flex;
    align-items: center;
    margin: 8px 0;
    padding-bottom: 4px;
    cursor: pointer;
}

.nav__logo--title {
    display: flex;
    font-weight: 500;
    font-size: 38px;
    padding-bottom: 2px;
    letter-spacing: 0.6px;
    font-family: 'Permanent Marker', cursive;
    color: black;
}

.nav__link--list {
    display: flex;
    gap: 70px; 
    list-style: none;
    align-items: center;
    font-size: 28px;
}

.nav__link--anchor {
    color: black; 
    text-decoration: none;
    font-family: 'Permanent Marker', cursive;
}

.link__hover-effect {
    position: relative;
    display: inline-block;
    padding-bottom: 4px; 
}

.link__hover-effect::after {
    content: "";
    position: absolute;
    left: 50%;
    bottom: 0;
    transform: translateX(-50%); 
    width: 0%;
    height: 4px;
    background-color: black;
    transition: width 0.3s ease;
}

