"import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import logoImg from '../assets/vecteezy_musical-head-phone-with-abstract-pulse-inside_.jpg';

export default function Navbar() {
  const navigate = useNavigate();

  const handlePlaylistClick = (e) => {
    e.preventDefault();
    navigate('/');
    // Smooth scroll to results
    setTimeout(() => {
      const resultsEl = document.getElementById('results');
      if (resultsEl) {
        resultsEl.scrollIntoView({ behavior: 'smooth' });
      }
    }, 100);
  };

  return (
    <nav>
      <div className="row nav__row">
        <Link to="/" className="nav__logo" style={{ textDecoration: 'none' }}>
          <img className="nav__logo--img" src={logoImg} alt="logo" />
          <div className="nav__logo--title">Vibe Frequency</div>
        </Link>

        <ul className="nav__link--list">
          <li className="nav__link">
            <Link to="/" className="nav__link--anchor link__hover-effect">Home</Link>
          </li>
          <li className="nav__link">
            <a href="#results" onClick={handlePlaylistClick} className="nav__link--anchor link__hover-effect">Playlist</a>
          </li>
          <li className="nav__link">
            <a href="#" onClick={(e) => e.preventDefault()} className="nav__link--anchor link__hover-effect" style={{ cursor: 'not-allowed', opacity: 0.6 }}>Sign Up</a>
          </li>
        </ul>
      </div>
    </nav>
  );
}
"

