"import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import logoImg from '../assets/vecteezy_musical-head-phone-with-abstract-pulse-inside_.jpg';

export default function Sidebar({ isOpen, onClose, onSignInClick }) {
  const navigate = useNavigate();

  const handleMenuClick = (action) => {
    onClose(); // Close mobile drawer if open

    if (action === 'podcasts') {
      alert('Podcasts are coming soon to Vibe Frequency!');
      return;
    }

    if (action === 'playlist') {
      navigate('/', { state: { action: 'playlist' } });
      // Wait for navigation to complete, then scroll
      setTimeout(() => {
        const resultsEl = document.getElementById('results');
        if (resultsEl) {
          resultsEl.scrollIntoView({ behavior: 'smooth' });
        }
      }, 100);
      return;
    }

    if (action === 'explore') {
      navigate('/', { state: { action: 'explore' } });
