    max-width: 1700px;         
    margin: 0 auto;            
    padding: 60px 20px; 
}

.footer__bottom {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
}

.footer__copyright {
    text-align: center;
    margin-top: 20px;
    font-size: 20px;
    color: #a7a7a7;
}

.footer__logo {
    display: flex;
    align-items: center;
    margin: 8px 0;
}

.footer__logo--img {
    height: 100px; 
    width: 100px;
    border-radius: 50%;
    object-fit: cover;
    background-color: #181818;
    padding: 10px;
    box-shadow: 0 4px 10px rgba(0,0,0,0.6);
    filter: invert(1) hue-rotate(180deg);
}

.footer__left {
    display: flex;
    align-items: center;
    gap: 12px;
    color: white;
}

.footer__logo--text {
    display: flex;
    font-weight: 500;
    font-size: 32px;
    letter-spacing: 1px;
    font-family: 'Permanent Marker', cursive;
    color: white;
}

.footer__logo--saying {
    display: flex;
    font-weight: 500;
    font-size: 32px;
    letter-spacing: 0.6px;
    font-family: 'Permanent Marker', cursive;
    color: white;
}

.footer__socials {
    display: flex;
    gap: 24px;
    align-items: center;
}

.footer__social-link {
    color: #b3b3b3;
    font-size: 30px;
    transition: color 0.2s ease, transform 0.2s ease;
}

.footer__social-link:hover {
    color: #a855f7;
    transform: scale(1.15);
}

.footer__meta-links {
    display: flex;
    justify-content: center;
    gap: 35px;
    margin-top: 30px;
    flex-wrap: wrap;
    border-top: 1px solid #181818;
    padding-top: 20px;
}

.footer__meta-link {
    color: #a7a7a7;
    font-size: 18px;
    transition: color 0.2s ease;
}

.footer__meta-link:hover {
    color: #ffffff;
    text-decoration: underline;
}

footer {
    background-color: #000000;
    width: 100%;
}"

